func:
// ===== Error 演练 =====
// 注意：本流没有 Catch 节点——被 Catch 处理的 error 不会写入日志，监控也就采集不到。

// 1) 固定消息：验证监控页「次数」去重计数
node.error("【演练】PLC-99 采集超时（固定消息，验证去重计数）", msg);

// 2) 每分钟变化的消息：验证多种错误并存
var minute = new Date().getMinutes();
node.error("【演练】数据库写入失败 batch-" + minute + "（变化消息，验证多条并存）", msg);

// 3) 每 5 次触发抛一次真实异常（带堆栈）
var n = context.get('count') || 0;
n++;
context.set('count', n);
if (n % 5 === 0) {
    throw new Error("【演练】第 " + n + " 次触发：模拟未捕获异常（带堆栈）");
}
return msg;
